item.text:
{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing reporting does not establish whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not establish variation across runs."
        }
      ],
      "instrument_review": "MESA 14 concerns whether repeated testing occurred; 16 concerns evidence about score variation. Both remain unresolved here."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly states that repeated testing did not occur."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once",
          "reason": "A single run cannot establish stability; it also does not demonstrate instability."
        }
      ],
      "instrument_review": "MESA 14 is explicitly unmet. Under MESA 16, evidence of score stability remains insufficient."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated testing under the same stated conditions occurred."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability criterion of at most two percentage points."
        }
      ],
      "instrument_review": "MESA 14 is supported by repeated testing. MESA 16 supports stability for this comparison under the stated criterion and conditions."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated testing occurred regardless of whether its findings were favourable."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the stated stability limit of two percentage points."
        }
      ],
      "instrument_review": "MESA 14 is supported because testing occurred. The findings relevant to MESA 16 contradict stability under the report's definition."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation guidance supplies no evidence that repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The new instructions provide no findings about score variation."
        }
      ],
      "instrument_review": "Installation guidance is relevant to MESA 22 on repeatability of methods, but it does not resolve MESA 14 or 16 on actual repeated testing and score variation."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A solved more evaluated puzzles under the stated scoring and conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The results provide insufficient evidence for a comparison of general intelligence across domains."
        }
      ],
      "instrument_review": "Under MESA 2, 20 and 25, the narrow comparison fits the intended use. Extending it to general intelligence would exceed the supplied evidence."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported results support A's better performance on these evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "Stating a broad intended use does not supply evidence for performance across domains."
        }
      ],
      "instrument_review": "MESA 2 identifies the broad intended use, but MESA 9 and 20 lack evidence supporting its coverage and generalization. Under MESA 25, a general-intelligence conclusion would exceed these findings."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone supply no demonstrated link to improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial with blinded correctness checks supports better correctness with A in the studied workshop; the difference interval was 12 to 28 percentage points."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Correctness findings do not establish an improvement in an unmeasured safety outcome."
        }
      ],
      "instrument_review": "For MESA 20, the later trial supplies evidence beyond test scores for workshop decision correctness. Its uncertainty interval informs MESA 16. Under MESA 25, claims should remain limited to the studied outcome, workshop and conditions."
    }
  ],
  "closing_note": "No material instructions were unclear. Probe labels classify statements rather than MESA ratings; missing evidence was distinguished from explicit contradiction. No aggregate quality score was calculated."
}
